"""Portable, escaped, read-only operations report. No external assets."""
import html


def render(snapshot):
    e=lambda x:html.escape(str(x),quote=True)
    sources=''.join(f'<tr><td>{e(s["id"])}</td><td>{e(s["status"])}</td><td>{e(s["succeeded"] or "Never")}</td><td>{e(s["publication_status"])}</td><td>{e(s["published"] or "Unknown")}</td><td>{s["failures"]}</td></tr>' for s in snapshot['sources'])
    incidents=''.join(f'<article><h3>{e(i["data"]["title"])}</h3><p>{e(i["data"]["status"])} · review: {e(i["review"])} · revision {i["revision"]}</p><p>{e(i["data"]["instruction"])}</p><p>Updated {e(i["data"]["updated"])} · expires {e(i["data"]["expires"] or "not supplied")}</p><a href="{e(i["data"]["url"])}" rel="noreferrer noopener">Original source</a><button class="speak">Read aloud</button></article>' for i in snapshot['incidents'])
    history=''.join(f'<details><summary>{e(h["at"])} · revision {h["revision"]} · {e(h["data"]["title"])}</summary><pre>{e(h["changes"])}</pre></details>' for h in snapshot['history'])
    return '''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>ÉireWatch · Monitor</title><style>body{font:16px system-ui;background:#07110D;color:#EDF7F1;max-width:1100px;margin:auto;padding:24px}h1,h2,a{color:#78E6AA}article,details{background:#0B1712;border:1px solid #1E3229;padding:18px;margin:14px 0;border-radius:12px}button{background:#12231B;color:#EDF7F1;border:1px solid #78E6AA;padding:10px;margin-left:12px;cursor:pointer}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:12px;border-bottom:1px solid #1E3229}pre{white-space:pre-wrap;overflow-wrap:anywhere}.table{overflow:auto}small{color:#8FA39A}</style><h1>Source health & incident changes</h1><p>Private operations snapshot. Not a live emergency service. Unavailable feeds do not mean an all-clear.</p><small>Generated '''+e(snapshot['generated'])+'''</small><h2>Source health</h2><div class="table"><table><tr><th>Source</th><th>State</th><th>Last success</th><th>Publication state</th><th>Feed publication</th><th>Failures</th></tr>'''+sources+'''</table></div><h2>Review queue & incidents</h2>'''+(incidents or '<p>No incidents loaded.</p>')+'''<h2>Revision history</h2>'''+(history or '<p>No revisions.</p>')+'''<script>document.querySelectorAll('.speak').forEach(b=>{if(!('speechSynthesis' in window)){b.disabled=true;b.textContent='Speech unavailable';return}b.onclick=()=>{speechSynthesis.cancel();speechSynthesis.speak(new SpeechSynthesisUtterance(b.closest('article').innerText.replace('Read aloud','')))}});window.addEventListener('pagehide',()=>{if('speechSynthesis' in window)speechSynthesis.cancel()});</script></html>'''
